pub(super) fn require_descriptors(
    files: &RootHostInitialGenerationFilesV1,
    purpose: LoadPurpose,
) -> Result<(), AgentdError> {
    let mut identities = BTreeSet::new();
    for (file, access) in [
        (&files.registry_snapshot, Access::ReadOnly),
        (&files.selected_payload, Access::ReadOnly),
        (&files.withdrawal_snapshot, Access::ReadOnly),
        (&files.target_journal, Access::ReadWrite),
        (&files.target_witness, Access::ReadWrite),
    ] {
        let metadata = file.metadata()?;
        require_private_file(&metadata)?;
        // SAFETY: F_GETFL inspects this borrowed, still-owned descriptor.
        let flags = unsafe { libc::fcntl(file.as_raw_fd(), libc::F_GETFL) };
        let expected = match access { Access::ReadOnly => libc::O_RDONLY, Access::ReadWrite => libc::O_RDWR };
        if flags < 0 || flags & libc::O_ACCMODE != expected
            || flags & libc::O_APPEND != 0
            || !identities.insert((metadata.dev(), metadata.ino()))
        {
            return Err(invalid("original generation descriptors must be distinct and have fixed access"));
        }
    }
    if matches!(purpose, LoadPurpose::Recover)
        && (files.target_journal.metadata()?.len() == 0 || files.target_witness.metadata()?.len() < 112)
    {
        return Err(invalid("original recovery cannot initialize an empty journal or witness"));
    }
    Ok(())
}

pub(super) fn require_artifact_directory(state: &Path, artifact: &Path) -> Result<(), AgentdError> {
    require_private_child(state, artifact)?;
    for name in ["writer", "transactions", "payloads", "registries", "witnesses", "heads"] {
        RootAuthorityDirectory::open(&artifact.join(name)).map_err(invalid)?;
    }
    let lock = open_private(&artifact.join("writer/owner.lock"))?;
    require_private_file(&lock.metadata()?)?;
    Ok(())
}

pub(super) fn require_existing_consumer(state: &Path, consumer: &Path) -> Result<(), AgentdError> {
    require_private_child(state, consumer)?;
    // These exact existing names distinguish this loader from the original
    // store's explicit first-start path. Do not call a genesis constructor.
    let lock = open_private(&consumer.join("authority.lock"))?;
    let claims = open_private(&consumer.join("authority.claims"))?;
    require_private_file(&lock.metadata()?)?;
    require_private_file(&claims.metadata()?)?;
    let mut header = open_private(&consumer.join("authority.json"))?;
    let before = header.metadata()?;
    if before.len() == 0 || before.len() > 8 * 1024 * 1024 {
        return Err(invalid("existing FinalUse state is absent or outside its original bound"));
    }
    let mut bytes = Vec::new();
    header.by_ref().take(8 * 1024 * 1024 + 1).read_to_end(&mut bytes)?;
    let after = header.metadata()?;
    if bytes.len() as u64 != before.len()
        || before.dev() != after.dev() || before.ino() != after.ino()
        || before.len() != after.len() || before.mtime() != after.mtime()
        || before.mtime_nsec() != after.mtime_nsec() || before.ctime() != after.ctime()
        || before.ctime_nsec() != after.ctime_nsec()
    {
        return Err(invalid("existing FinalUse header changed during bounded observation"));
    }
    let value: serde_json::Value = serde_json::from_slice(&bytes).map_err(invalid)?;
    if value.get("schema").and_then(serde_json::Value::as_u64) != Some(3) {
        return Err(invalid("this open-only loader requires the existing FinalUse journal schema"));
    }
    // Full trust, head and every nonce are subsequently verified by the actual
    // original FinalUse factory. This header observation grants no authority.
    Ok(())
}

fn require_private_child(state: &Path, path: &Path) -> Result<(), AgentdError> {
    if !state.is_absolute() || !path.is_absolute() || path == state || !path.starts_with(state)
        || path.components().any(|part| !matches!(part, Component::RootDir | Component::Normal(_)))
    {
        return Err(invalid("generation state must be an existing private child of the same Root state"));
    }
    RootAuthorityDirectory::open(path).map_err(invalid)?;
    Ok(())
}

fn open_private(path: &Path) -> Result<File, AgentdError> {
    let parent = path.parent().ok_or_else(|| invalid("missing original state parent"))?;
    RootAuthorityDirectory::open(parent).map_err(invalid)?;
    let file = OpenOptions::new().read(true)
        .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW | libc::O_NONBLOCK).open(path)?;
    require_private_file(&file.metadata()?)?;
    Ok(file)
}

fn require_private_file(metadata: &std::fs::Metadata) -> Result<(), AgentdError> {
    if !metadata.is_file() || metadata.uid() != 0
        || metadata.mode() & 0o777 != 0o600 || metadata.nlink() != 1
    {
        return Err(invalid("original generation input must be a Root0600 single-link regular file"));
    }
    Ok(())
}

pub(crate) fn load_original_initial_generation_inputs(
    &self,
    original_state: &Path,
    deployment: &Path,
    original_files: RootHostInitialGenerationFilesV1,
    purpose: LoadPurpose,
    end: Instant,
) -> Result<LoadedOriginalGeneration, AgentdError> {
    require_before(end)?;
    let value: GenerationDeploymentFile = read_root_json(deployment)?;
    if value.schema_version != 1
        || value.purpose != "hepta.root.initial-generation.existing-inputs.v1"
        || !matches!((purpose, &value.operation),
            (LoadPurpose::Fresh, OperationFile::Fresh { .. })
            | (LoadPurpose::Recover, OperationFile::Recover { .. }))
    {
        return Err(invalid("original generation deployment purpose differs"));
    }
    files::require_descriptors(&original_files, purpose)?;
    files::require_artifact_directory(original_state, &value.artifacts.state_directory)?;
    files::require_existing_consumer(original_state, &value.consumer.state_directory)?;
    if value.artifacts.state_directory == value.consumer.state_directory {
        return Err(invalid("Artifact and FinalUse retain separate original stores"));
    }
    let root = Arc::clone(self.resident_store_root.as_ref()
        .ok_or_else(|| invalid("the same original Root directory must be retained"))?);
    if self.root_registry.is_none() {
        return Err(invalid("the same original lease Registry must be retained"));
    }
    let RootHostInitialGenerationFilesV1 {
        registry_snapshot, selected_payload, withdrawal_snapshot, target_journal, target_witness,
    } = original_files;
    let trust = value.artifacts.trust.original()?;
    let verifier = ArtifactSelectionVerifierV1::new(value.selection.trust.original()?, &trust)
        .map_err(invalid)?;
    let signed_selection = value.selection.signed.original()?;
    let writer_lease = value.artifacts.writer_lease.original()?;
    let required_current_head = value.artifacts.required_current_head.original()?;
    let withdrawal_registry = read_dataset_withdrawal_snapshot(
        withdrawal_snapshot, value.artifacts.withdrawal_snapshot.original(),
    ).map_err(invalid)?;
    require_before(end)?;
    let artifacts = LearningArtifactOwnerService::open(LearningArtifactOwnerServiceConfigV1 {
        root: value.artifacts.state_directory,
        trust,
        writer_lease,
        required_current_head: Some(required_current_head),
        withdrawal_registry,
        storage_binding: Digest32::from_array(value.artifacts.storage_binding),
        now: self.clock.now_unix_ms().map_err(invalid)?,
    }).map_err(invalid)?;
    let selected = AgentdSelectedGenerationV1::load(
        &artifacts, verifier, signed_selection,
        AgentdGenerationSelectionFilesV1 { registry_snapshot, payload: selected_payload },
        self.clock.now_unix_ms().map_err(invalid)?,
    )?;
    require_before(end)?;
    // The protected file names an already existing generation nonce owner.
    // The original issuer verifier binds its grant signer to this key id,
    // and FinalUse::claim binds that signer to the nonce owner in BOTH trust
    // models. Keep the explicit owner id and check this original relation.
    let key = self.issuer.trust_key()?;
    let head = self.issuer.revocations()?;
    let owner_id = value.consumer.owner_id;
    if owner_id != key.key_id
        || matches!(&value.operation, OperationFile::Fresh { signed, .. } if signed.grant.signer_id != owner_id)
    {
        return Err(invalid("the existing generation consumer differs from the original grant signer"));
    }
    let frontier = Arc::new(HostAuthorityFrontierStore::<FinalUseFrontier>::open(
        root, owner_id.clone(),
    ).map_err(invalid)?);
    if frontier.load(&owner_id).map_err(invalid)? != value.consumer.required_external_frontier {
        return Err(invalid("the existing generation consumer frontier differs from its complete pin"));
    }
    let final_use = match value.consumer.trust_model {
        ConsumerTrustModel::SingleCurrentIssuer => {
            FinalUseAuthority::open_state_dir_with_trust(
                &value.consumer.state_directory, owner_id, key.verifying_key,
                head.clone(), self.clock.clone(), frontier,
            )
        }
        ConsumerTrustModel::CurrentIssuerKeyRing => FinalUseAuthority::open_state_dir_with_issuer_keys(
            &value.consumer.state_directory, owner_id,
            vec![key], head.clone(), self.clock.clone(), frontier,
        ),
    }.map_err(invalid)?;
    if final_use.current_external_frontier().map_err(invalid)? != value.consumer.required_external_frontier
        || final_use.revocation_head().map_err(invalid)? != head
        || self.issuer.revocations()? != head
    {
        return Err(invalid("the original issuer or consumer changed while loading"));
    }
    require_before(end)?;
    let configuration = value.target.configuration;
    let binding = CellGenerationOwnerBindingV1::new(&configuration, value.target.maximum_records)
        .map_err(invalid)?;
    // Fresh input may initialize the header of its explicitly supplied
    // empty witness. Recovery was rejected before any such original open.
    let witness = FileAnchorWitnessStore::open(
        target_witness,
        JournalScope {
            scope_digest: Digest32::from_array(binding.digest().map_err(invalid)?),
            objective_digest: Digest32::from_array(configuration.task_digest),
        },
        Generation::new(configuration.initial.generation).map_err(invalid)?,
        value.target.maximum_witness_records,
    ).map_err(invalid)?;
    let target = AgentdGenerationUpdateTargetV1 {
        file: target_journal, witness, config: configuration,
        max_records: value.target.maximum_records,
    };
    let artifacts = Arc::new(Mutex::new(artifacts));
    let final_use = Arc::new(final_use);
    require_before(end)?;
    Ok(match value.operation {
        OperationFile::Fresh { operation_id, signed } => LoadedOriginalGeneration::Fresh(
            RootHostInitialGenerationInputsV1 {
                artifacts, final_use, selected, target,
                request: AgentdGenerationUpdateRequestV1 { operation_id }, signed,
            },
        ),
        OperationFile::Recover { operation_id, intent_digest } => LoadedOriginalGeneration::Recover(
            RootHostInitialGenerationRecoveryV1 {
                artifacts, final_use, selected, target,
                recovery: AgentdGenerationUpdateRecoveryV1 {
                    operation_id, intent_digest: Digest32::from_array(intent_digest),
                },
            },
        ),
    })
}

fn require_before(end: Instant) -> Result<(), AgentdError> {
    // SAFETY: these calls inspect only the actual current process credentials.
    if unsafe { libc::getuid() } != 0 || unsafe { libc::geteuid() } != 0 || Instant::now() >= end {
        return Err(invalid("the original Root input-loading window ended"));
    }
    Ok(())
}

fn original(self) -> Result<TrustedArtifactSignerV1, AgentdError> {
    Ok(TrustedArtifactSignerV1 {
        signer_id: StableId::new(self.signer_id).map_err(invalid)?,
        verifying_key: self.verifying_key,
        minimum_authority_epoch: self.minimum_authority_epoch,
        maximum_authority_epoch: self.maximum_authority_epoch,
        valid_from: self.valid_from,
        expires_at: self.expires_at,
        revoked_at: self.revoked_at,
    })
}

pub(super) fn original(self) -> Result<ArtifactOwnerTrustV1, AgentdError> {
    Ok(ArtifactOwnerTrustV1 {
        registry_id: StableId::new(self.registry_id).map_err(invalid)?,
        withdrawal_scope_digest: Digest32::from_array(self.withdrawal_scope_digest),
        minimum_registry_generation: Generation::new(self.minimum_registry_generation).map_err(invalid)?,
        genesis_predecessor_head_digest: Digest32::from_array(self.genesis_predecessor_head_digest),
        minimum_authority_epoch: self.minimum_authority_epoch,
        writer_signers: self.writer_signers.into_iter().map(SignerFile::original).collect::<Result<_, _>>()?,
        head_signers: self.head_signers.into_iter().map(SignerFile::original).collect::<Result<_, _>>()?,
    })
}

pub(super) fn original(self) -> Result<SignedCurrentArtifactHeadV1, AgentdError> {
    let w = self.witness;
    Ok(SignedCurrentArtifactHeadV1 {
        withdrawal_scope_digest: Digest32::from_array(self.withdrawal_scope_digest),
        binding: Digest32::from_array(self.binding),
        witness: RegistryHeadWitnessV1 {
            registry_id: StableId::new(w.registry_id).map_err(invalid)?,
            generation: Generation::new(w.generation).map_err(invalid)?,
            head_digest: Digest32::from_array(w.head_digest),
            predecessor_head_digest: Digest32::from_array(w.predecessor_head_digest),
            authority_epoch: w.authority_epoch,
            signer_id: StableId::new(w.signer_id).map_err(invalid)?,
            signing_key_digest: Digest32::from_array(w.signing_key_digest),
            issued_at: w.issued_at,
            expires_at: w.expires_at,
        },
        signature: signature(self.signature)?,
    })
}

pub(super) fn original(self) -> DatasetWithdrawalSnapshotReceiptV1 {
    DatasetWithdrawalSnapshotReceiptV1 {
        binding: Digest32::from_array(self.binding),
        scope_digest: Digest32::from_array(self.scope_digest),
        head_digest: Digest32::from_array(self.head_digest),
        file_digest: Digest32::from_array(self.file_digest),
        records: self.records,
        encoded_bytes: self.encoded_bytes,
    }
}

pub(super) fn original(self) -> Result<ArtifactSelectionTrustV1, AgentdError> {
    let selectors = self.selectors.into_iter().map(|v| {
        Ok(TrustedArtifactSelectorV1 {
            selector_id: StableId::new(v.selector_id).map_err(invalid)?,
            verifying_key: v.verifying_key,
            minimum_authority_epoch: v.minimum_authority_epoch,
            maximum_authority_epoch: v.maximum_authority_epoch,
            valid_from: v.valid_from,
            expires_at: v.expires_at,
            revoked_at: v.revoked_at,
        })
    }).collect::<Result<Vec<_>, AgentdError>>()?;
    Ok(ArtifactSelectionTrustV1 {
        registry_id: StableId::new(self.registry_id).map_err(invalid)?,
        withdrawal_scope_digest: Digest32::from_array(self.withdrawal_scope_digest),
        minimum_authority_epoch: self.minimum_authority_epoch,
        selectors,
    })
}

fn signature(bytes: Vec<u8>) -> Result<[u8; 64], AgentdError> {
    bytes.try_into().map_err(|_: Vec<u8>| invalid("original signature must contain 64 bytes"))
}

pub fn prepare_original_initial_generation_from_files(
    self,
    deployment: &Path,
    files: RootHostInitialGenerationFilesV1,
) -> Result<PreparedRootHostInitialGenerationV1<FileAnchorWitnessStore>, AgentdError> {
    let end = Instant::now() + Duration::from_millis(self.config.timeout_ms);
    require_original_session(&self, end)?;
    let OriginalLoadedGeneration::Fresh(inputs) = HostAuthorityService::load_original_initial_generation_inputs(
        &self.service, &self.config.state_dir, deployment, files, OriginalGenerationLoadPurpose::Fresh, end,
    )? else {
        return Err(invalid("the fixed Fresh input loader returned another purpose"));
    };
    let operation = HostAuthorityService::bind_original_initial_operation(&self.service, &inputs, end)?;
    require_original_session(&self, end)?;
    Ok(PreparedRootHostInitialGenerationV1 {
        session: self, operation, phase: InitialHostPhase::Fresh(inputs), end,
    })
}

pub fn recover_original_initial_generation_from_files(
    self,
    deployment: &Path,
    files: RootHostInitialGenerationFilesV1,
) -> Result<PreparedRootHostInitialGenerationV1<FileAnchorWitnessStore>, AgentdError> {
    let end = Instant::now() + Duration::from_millis(self.config.timeout_ms);
    require_original_session(&self, end)?;
    let OriginalLoadedGeneration::Recover(inputs) = HostAuthorityService::load_original_initial_generation_inputs(
        &self.service, &self.config.state_dir, deployment, files, OriginalGenerationLoadPurpose::Recover, end,
    )? else {
        return Err(invalid("the fixed recovery loader returned another purpose"));
    };
    let (operation, custody) = HostAuthorityService::recover_original_initial_operation(&self.service, inputs, end)?;
    require_original_session(&self, end)?;
    Ok(PreparedRootHostInitialGenerationV1 {
        session: self, operation, phase: InitialHostPhase::Ready(custody), end,
    })
}

pub(super) fn new(end: Instant) -> Self {
    Self { first_failure: Arc::new(AtomicU8::new(0)), end }
}

pub(super) fn record_original_error(&self, error: AuthorityTrustError) {
    let code = match error {
        AuthorityTrustError::Invalid => 1,
        AuthorityTrustError::Conflict => 2,
        AuthorityTrustError::Unavailable => 3,
    };
    self.record(code);
}

fn record(&self, code: u8) {
    // Preserve the first actual cause even if later clock reads recover,
    // another failure happens, or the absolute end subsequently expires.
    let _ = self.first_failure.compare_exchange(0, code, Ordering::AcqRel, Ordering::Acquire);
}

pub(crate) fn require_healthy(&self) -> Result<(), AgentdError> {
    if Instant::now() >= self.end { self.record(5); }
    let message = match self.first_failure.load(Ordering::Acquire) {
        0 => return Ok(()),
        1 => "original protected task clock: Invalid",
        2 => "original protected task clock: Conflict",
        3 => "original protected task clock: Unavailable",
        4 => "original protected task clock: microsecond projection overflow",
        5 => "original protected task clock: absolute task end expired",
        _ => "original protected task clock: invalid retained failure state",
    };
    Err(invalid(message))
}

pub(super) fn require_descriptors(
    files: &RootHostQ24TaskFilesV1,
    purpose: TaskFilePurpose,
) -> Result<(), AgentdError> {
    let mut identities = BTreeSet::new();
    for (file, access) in [
        (&files.source_journal, Access::ReadWrite),
        (&files.source_witness, Access::ReadWrite),
        (&files.cell_journal, Access::ReadWrite),
        (&files.cell_witness, Access::ReadWrite),
        (&files.inference_control, Access::ReadAppend),
        (&files.model.base, Access::ReadOnly),
        (&files.model.encoder, Access::ReadOnly),
        (&files.model.heads, Access::ReadOnly),
    ] {
        require_one(file, access, &mut identities)?;
    }
    for file in [files.model.organ_adapter.as_ref(), files.model.cell_adapter.as_ref()]
        .into_iter().flatten()
    {
        require_one(file, Access::ReadOnly, &mut identities)?;
    }
    if purpose == TaskFilePurpose::Recover
        && (files.source_journal.metadata()?.len() == 0
            || files.cell_journal.metadata()?.len() == 0
            || files.source_witness.metadata()?.len() < 112
            || files.cell_witness.metadata()?.len() < 112)
    {
        return Err(invalid("task recovery cannot initialize an absent journal or witness history"));
    }
    // A real existing control journal may have no entries before first
    // execution. Its original replay and the same Source/Cell receipts decide
    // whether readback is possible; absence is never translated into Execute.
    Ok(())
}

fn require_one(
    file: &File,
    access: Access,
    identities: &mut BTreeSet<(u64, u64)>,
) -> Result<(), AgentdError> {
    let metadata = file.metadata()?;
    if !metadata.is_file() || metadata.uid() != 0
        || metadata.mode() & 0o7777 != 0o600 || metadata.nlink() != 1
        || !identities.insert((metadata.dev(), metadata.ino()))
    {
        return Err(invalid("task files must be distinct Root0600 single-link regular descriptors"));
    }
    // SAFETY: F_GETFL observes this borrowed descriptor; ownership stays here.
    let flags = unsafe { libc::fcntl(file.as_raw_fd(), libc::F_GETFL) };
    let (mode, append) = match access {
        Access::ReadOnly => (libc::O_RDONLY, 0),
        Access::ReadWrite => (libc::O_RDWR, 0),
        Access::ReadAppend => (libc::O_RDWR, libc::O_APPEND),
    };
    if flags < 0 || flags & libc::O_ACCMODE != mode || flags & libc::O_APPEND != append {
        return Err(invalid("task descriptor access or append mode differs from its fixed role"));
    }
    Ok(())
}

